// ANÁLISE DE DADOS E STORYTELLING — NÍVEL BÁSICO (30 lições, todas de quiz: tabelas, gráficos, contas conferidas, escrita com as próprias palavras).
// Bloco 1 (1–10): pensar com dados: perguntas, tipos de dados, tabelas, fontes, limpeza, média, mediana e moda.  Checkpoint depois da 10.
// Bloco 2 (11–20): resumir e comparar: mínimo e máximo, porcentagem, variação, grupos, tendência, correlação, amostra, escolha do gráfico.  Checkpoint depois da 20.
// Bloco 3 (21–30): visualizar e contar a história (storytelling): gráficos que enganam, gráfico limpo, títulos, público, insight, estrutura, recomendação, painel, ética.  Prova final depois da 30.
// As contas das perguntas numéricas são refeitas em JavaScript (`calc`) por `npm run check:pbi`.
const { Q } = require('./hp')('dados', 1);
const { mc, multi, order, match, num, build, write, tab, col } = require('./hp');

const sum = a => a.reduce((x, y) => x + y, 0), avg = a => sum(a) / a.length, med = a => { const s = [...a].sort((x, y) => x - y), n = s.length; return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2; };
const r1 = x => Math.round(x * 10) / 10, r2 = x => Math.round(x * 100) / 100;
const CAT = ['Bebidas', 'Doces', 'Lanches'], CAT_V = [215, 192, 340];
const MES = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez'];
const V23 = [37, 12, 64, 40, 36, 50, 24, 38, 17, 13, 40, 25], V24 = [7, 14, 36, 26, 40, 76, 14, 34, 6, 66, 14, 18];

exports.lessons = [
  // ------------------------------------------------------------------ bloco 1: pensar com dados
  Q('O que é análise de dados', 'Analisar dados é olhar para números e informações organizadas para responder uma pergunta e ajudar a decidir o que fazer. Toda análise segue um caminho: perguntar, reunir os dados, limpar, analisar, visualizar e contar o que descobriu.',
    'Pergunta: qual categoria vende mais?\nDados: tabela de vendas\nAnálise: somar o valor por categoria\nResposta: "Lanches lidera as vendas"', 'Responda sobre o que é análise de dados e coloque as etapas na ordem.', [
      order('Coloque as etapas de uma análise de dados na ordem certa:', ['Fazer a pergunta', 'Reunir os dados', 'Limpar e organizar', 'Analisar: calcular e comparar', 'Visualizar e contar a história'], 'A pergunta vem primeiro: ela diz quais dados buscar. Depois vêm reunir, limpar, analisar e, por fim, mostrar o resultado de um jeito fácil de entender.'),
      mc('Para que serve analisar dados?', 'Para responder perguntas e apoiar decisões com base em evidências', ['Para guardar todos os arquivos da empresa num lugar só', 'Para deixar as planilhas mais bonitas e coloridas', 'Para trocar toda decisão por um palpite'], 'Analisar dados é **transformar números em respostas** que ajudam a decidir melhor, em vez de decidir no palpite.'),
      match('Ligue cada etapa ao que se faz nela:', [['Reunir os dados', 'Buscar as tabelas e fontes que respondem à pergunta'], ['Limpar', 'Corrigir erros, tirar repetidos e tratar vazios'], ['Analisar', 'Calcular totais, médias e comparações'], ['Visualizar', 'Montar gráficos e tabelas fáceis de entender']], 'Cada etapa tem um trabalho: **reunir** traz os dados, **limpar** arruma, **analisar** calcula e **visualizar** mostra.'),
      mc('Olhando o gráfico, qual é a resposta para "qual categoria vende mais?"', 'Lanches', ['Bebidas', 'Doces', 'Todas vendem igual'], 'A coluna de **Lanches** (R$ 340,00) é a mais alta. O gráfico responde a pergunta de relance.', { chart: col(CAT, CAT_V, { title: 'Vendas por categoria', fmt: 'moeda' }), calc: () => CAT[CAT_V.indexOf(Math.max(...CAT_V))] }),
      multi('Quais destas perguntas dá para responder com uma tabela de vendas?', ['Qual mês vendeu mais?', 'Qual produto vende mais no canal Online?', 'As vendas caíram de um ano para o outro?'], ['Qual música os clientes preferem?', 'O vendedor estava de bom humor?'], 'Uma tabela de vendas guarda **o que, quando, quanto e onde** se vendeu. Gosto musical e humor não estão nela.')
    ], { mat: { chart: col(CAT, CAT_V, { title: 'Exemplo: vendas por categoria', fmt: 'moeda' }) }, hint: 'Pense numa receita: primeiro decida o prato (a pergunta), depois busque os ingredientes (os dados).' }),

  Q('Como fazer boas perguntas', 'Uma boa pergunta de análise é específica: diz o quê, quando e como medir. "As vendas vão bem?" é vaga. "As vendas de 2024 cresceram em relação às de 2023?" dá para responder com números.',
    'Vaga:       "As vendas vão bem?"\nEspecífica: "As vendas de 2024 cresceram em relação a 2023?"', 'Aprenda a transformar uma pergunta vaga numa pergunta que os dados conseguem responder.', [
      mc('Qual é a melhor pergunta para começar uma análise?', 'Qual categoria mais caiu de 2023 para 2024?', ['Será que as vendas estão boas para o nosso porte?', 'Como anda a loja de modo geral nos últimos tempos?', 'O que os clientes acham de tudo o que fazemos?'], 'A melhor pergunta diz **o quê** (categoria), **quando** (2023 e 2024) e **o que medir** (queda de vendas).'),
      match('Ligue cada pergunta vaga à versão específica:', [['Vendemos bem?', 'Quanto vendemos por mês em 2024, comparado com 2023?'], ['O cliente está satisfeito?', 'Qual é a nota média que os clientes deram neste mês?'], ['O produto é popular?', 'Quantas unidades foram vendidas nos últimos 3 meses?']], 'A pergunta específica traz **um número para calcular** e **um período**. Assim sabemos exatamente quais dados buscar.'),
      multi('Uma boa pergunta de análise costuma ter:', ['Um assunto claro (o quê)', 'Um período (quando)', 'Algo que dá para medir'], ['Várias perguntas misturadas numa só', 'A resposta já escolhida antes de olhar os dados'], 'Assunto, período e medida deixam a pergunta **clara e respondível**. Perguntas misturadas ou respostas prontas atrapalham.'),
      mc('Pergunta: "Quanto cada categoria vendeu em 2024?" Quais dados precisamos?', 'Valor da venda, categoria do produto e data da venda', ['Só o nome de cada cliente e a cidade onde ele mora', 'O telefone e o e-mail dos clientes que compraram', 'O endereço da loja e o horário de abertura dela'], 'Para somar **por categoria** e **por ano**, precisamos do valor, da categoria e da data.'),
      num('Pelo gráfico, quantos reais a mais a loja vendeu em 2023 do que em 2024?', 45, '396 − 351 = **45**. Uma pergunta bem feita ("quanto a mais?") vira uma conta simples.', { chart: col(['2023', '2024'], [sum(V23), sum(V24)], { title: 'Total de vendas por ano', fmt: 'moeda' }), unit: 'reais', calc: () => sum(V23) - sum(V24) }),
      mc('Por que definir a pergunta antes de abrir os dados?', 'Para saber quais dados buscar e não se perder em números', ['Porque os dados só abrem depois que a pergunta é aprovada', 'Porque assim a análise sempre confirma o que já pensávamos', 'Porque perguntas curtas dão sempre respostas certas'], 'Sem pergunta, é fácil **se perder** em tabelas enormes. A pergunta é a bússola da análise.')
    ], { hint: 'Boa pergunta: tem assunto, tem período e dá para responder com um número.' }),

  Q('Tipos de dados', 'Os dados são de dois grandes tipos. Os numéricos são quantidades (idade, valor) e podem ser contados (discretos: 0, 1, 2) ou medidos (contínuos: 1,72 m). Os categóricos são grupos: nominais (cidade, cor) ou ordinais, com uma ordem (ruim, bom, ótimo).',
    'Cidade → categórico nominal\nSatisfação (ruim, bom, ótimo) → categórico ordinal\nFilhos (0, 1, 2) → numérico discreto\nAltura (1,72) → numérico contínuo', 'Descubra o tipo de cada dado e quais deles fazem sentido para somar ou calcular média.', [
      match('Ligue cada dado ao seu tipo:', [['Cidade do cliente', 'Categórico nominal'], ['Satisfação: ruim, bom ou ótimo', 'Categórico ordinal'], ['Número de filhos (0, 1, 2...)', 'Numérico discreto'], ['Altura em metros (1,72)', 'Numérico contínuo']], '**Nominal** não tem ordem, **ordinal** tem. **Discreto** se conta, **contínuo** se mede.'),
      mc('Qual destes dados é categórico (qualitativo)?', 'A cor favorita do cliente', ['A quantidade de itens comprados', 'O valor total da compra', 'O tempo de espera em minutos'], 'A cor é um **grupo** (azul, verde...). Os outros são quantidades que podemos somar ou calcular a média.'),
      multi('Em quais destes dados faz sentido calcular a soma ou a média?', ['Quantidade vendida', 'Valor da venda', 'Horas trabalhadas na semana'], ['CEP do cliente', 'Número de telefone'], 'Só faz sentido somar o que é **quantidade**. CEP e telefone são **códigos**: somá-los não quer dizer nada.'),
      mc('O tamanho da camiseta (P, M, G, GG) é um dado:', 'Categórico ordinal', ['Numérico contínuo', 'Numérico discreto', 'Categórico nominal'], 'P, M, G e GG são grupos **com uma ordem** (de menor para maior): isso é ordinal.'),
      num('Quantas colunas da tabela têm números que fazem sentido somar ou tirar a média?', 2, 'Pedido é só um código de identificação. Só **Qtd e Valor** são quantidades de verdade: 2 colunas.', { table: tab(['Pedido', 'Cliente', 'Qtd', 'Valor', 'Pago?'], [[101, 'Ana', 2, 18, 'Sim'], [102, 'Bruno', 1, 6, 'Não'], [103, 'Carla', 3, 21, 'Sim']], { title: 'Tabela de pedidos', fmt: { 3: 'moeda' } }), calc: () => 2 })
    ], { hint: 'Pergunte: dá para somar isso e o resultado fazer sentido? Se sim, é numérico.' }),

  Q('Linhas, colunas e tabelas', 'Numa tabela, cada linha é um registro (uma venda, um cliente) e cada coluna é uma característica dele. É importante saber o que UMA linha representa, porque isso decide como contar e somar sem repetir nada.',
    'Linha = um item de um pedido\nColuna = Produto, Qtd...', 'Leia uma tabela, descubra o que cada linha representa e conte linhas e pedidos.', [
      mc('O que representa cada linha desta tabela?', 'Um item de um pedido', ['Um cliente', 'Um produto do cardápio', 'Um mês do ano'], 'Cada linha traz um produto de um pedido. O pedido 1 aparece em duas linhas porque tem **dois itens**.', { table: tab(['Pedido', 'Produto', 'Qtd'], [[1, 'Pastel', 2], [1, 'Suco', 1], [2, 'Pizza', 1], [3, 'Pastel', 3]], { title: 'Itens dos pedidos' }) }),
      num('Quantas linhas tem a tabela?', 4, 'São 4 linhas: Pastel, Suco, Pizza e Pastel.', { table: tab(['Pedido', 'Produto', 'Qtd'], [[1, 'Pastel', 2], [1, 'Suco', 1], [2, 'Pizza', 1], [3, 'Pastel', 3]], { title: 'Itens dos pedidos' }), calc: () => 4 }),
      num('Quantos pedidos diferentes existem na tabela?', 3, 'Os números de pedido são 1, 1, 2 e 3. Sem repetir: **3 pedidos**. Contar linhas daria 4, que é o número de itens.', { table: tab(['Pedido', 'Produto', 'Qtd'], [[1, 'Pastel', 2], [1, 'Suco', 1], [2, 'Pizza', 1], [3, 'Pastel', 3]], { title: 'Itens dos pedidos' }), calc: () => new Set([1, 1, 2, 3]).size }),
      multi('Numa tabela de clientes (uma linha por cliente), quais colunas combinam?', ['Nome do cliente', 'Cidade do cliente', 'Data de cadastro'], ['Valor de cada compra feita', 'Produto de cada pedido'], 'Nome, cidade e cadastro aparecem **uma vez por cliente**. Valor e produto de cada compra pertencem a outra tabela: a de vendas.'),
      mc('Por que é importante saber o que uma linha representa?', 'Para não contar ou somar a mesma coisa duas vezes', ['Porque linhas mais longas valem mais pontos', 'Porque toda tabela precisa ter exatamente dez linhas', 'Porque as colunas ficam de enfeite'], 'Se uma linha é um **item** e você conta linhas achando que são **pedidos**, o resultado fica errado.')
    ], { hint: 'Antes de contar ou somar, pergunte: UMA linha é o quê?' }),

  Q('De onde vêm os dados', 'Dados podem vir de sistemas da própria empresa (vendas, cadastro), de pesquisas feitas por você, de arquivos de outras pessoas e de sites. Antes de usar, confira se a fonte é atual, completa e confiável, porque uma análise só é boa se os dados forem bons.',
    'Sistema de vendas: dados da loja\nPesquisa: dados que você coleta\nSite público: dados de outras pessoas', 'Reconheça as fontes de dados e os sinais de uma fonte confiável.', [
      match('Ligue cada fonte ao exemplo:', [['Sistema da empresa', 'O registro de vendas da loja'], ['Pesquisa feita por você', 'Um formulário respondido pelos clientes'], ['Arquivo de outra pessoa', 'Uma planilha enviada pela matriz'], ['Site público', 'Números divulgados por um órgão do governo']], 'Cada fonte tem **dono e jeito de coleta** diferentes. Conhecer a origem ajuda a confiar (ou desconfiar) dos números.'),
      multi('Quais são sinais de uma fonte de dados confiável?', ['Diz quem coletou e quando', 'Está atualizada', 'Tem as informações completas, sem buracos grandes'], ['Não explica de onde vieram os números', 'Tem números "redondos" demais e nenhuma data'], 'Fonte boa é **clara, atual e completa**. Sem origem ou data, não dá para saber se vale a pena confiar.'),
      mc('Uma pesquisa de satisfação foi feita só com clientes que saíam da loja sorrindo. O que há de errado?', 'A amostra é enviesada: só ouviu gente feliz', ['Nada de errado: sorrir é apenas um dado numérico comum', 'Está tudo certo: quem sorri responde mais rápido', 'O problema é que a pesquisa foi curta demais'], 'Perguntar só para um tipo de pessoa gera **viés**: o resultado parece bom, mas não representa todos os clientes.'),
      mc('Qual destes é um dado primário (coletado por você mesmo)?', 'Um questionário que você mesmo criou e enviou', ['Um relatório de mercado comprado de uma consultoria', 'Uma tabela de população baixada de um site público', 'Uma planilha que um colega encontrou na internet'], 'Dado **primário** é o que você mesmo coleta. Os outros são dados **secundários**: já foram reunidos por outras pessoas.'),
      mc('Você recebeu uma planilha sem data, sem autor e com números estranhos. O que fazer?', 'Descobrir a origem e conferir os números antes', ['Usar do jeito que está: planilha é sempre confiável', 'Apagar as colunas estranhas e seguir em frente', 'Publicar logo para ninguém questionar depois'], 'Antes de analisar, **confirme a origem**. Conclusões feitas com dados duvidosos podem levar a decisões erradas.')
    ], { hint: 'Desconfie de dados sem origem, sem data ou que só ouviram um tipo de pessoa.' }),

  Q('Limpeza: vazios e repetidos', 'Dados reais vêm sujos. Alguns campos ficam vazios (ausentes) e algumas linhas aparecem repetidas. Antes de analisar, é preciso decidir o que fazer com cada caso: completar, remover ou deixar de fora do cálculo.',
    'Linha repetida  → remover uma das cópias\nCampo vazio     → completar, ou ignorar no cálculo', 'Ache os problemas numa tabela e decida como tratar cada um.', [
      num('Quantas linhas estão repetidas (cópias da mesma venda)?', 1, 'A venda 102 aparece duas vezes, com os mesmos dados. A segunda é uma **cópia repetida**: 1 linha.', { table: tab(['Pedido', 'Cliente', 'Cidade', 'Valor'], [[101, 'Ana', 'São Paulo', 120], [102, 'Bruno', 'Rio', 80], [102, 'Bruno', 'Rio', 80], [103, 'Carla', null, 95], [104, 'Diego', 'São Paulo', 150], [105, 'Elisa', 'Rio', null]], { title: 'Pedidos recebidos', fmt: { 3: 'moeda' } }), calc: () => 1 }),
      num('Quantas células estão vazias (sem informação) na tabela?', 2, 'Falta a cidade da Carla e o valor da Elisa: **2 células vazias**.', { table: tab(['Pedido', 'Cliente', 'Cidade', 'Valor'], [[101, 'Ana', 'São Paulo', 120], [102, 'Bruno', 'Rio', 80], [102, 'Bruno', 'Rio', 80], [103, 'Carla', null, 95], [104, 'Diego', 'São Paulo', 150], [105, 'Elisa', 'Rio', null]], { title: 'Pedidos recebidos', fmt: { 3: 'moeda' } }), calc: () => 2 }),
      mc('O que fazer com a linha repetida do pedido 102?', 'Remover uma das cópias, para a venda não ser contada duas vezes', ['Somar as duas linhas para ter mais precisão', 'Deixar as duas: mais linhas, mais dados', 'Apagar o pedido 102 inteiro das duas linhas'], 'Uma venda repetida **infla os totais**. Mantemos uma cópia e removemos a outra.'),
      num('Depois de remover a cópia repetida, qual é a soma da coluna Valor (os vazios não entram)?', 445, '120 + 80 + 95 + 150 = **445** (a venda do Bruno entra uma vez só).', { table: tab(['Pedido', 'Cliente', 'Valor'], [[101, 'Ana', 120], [102, 'Bruno', 80], [103, 'Carla', 95], [104, 'Diego', 150], [105, 'Elisa', null]], { title: 'Pedidos sem a cópia repetida', fmt: { 2: 'moeda' } }), unit: 'reais', calc: () => 120 + 80 + 95 + 150 }),
      mc('O valor do pedido 105 está vazio. Qual é a atitude mais honesta?', 'Procurar o valor correto na fonte; se não achar, deixar de fora do cálculo e avisar', ['Escrever zero e seguir: ninguém vai perceber', 'Inventar um valor parecido com os outros pedidos', 'Apagar todos os pedidos da Elisa'], 'Colocar **zero** ou **inventar** um número esconde o problema e muda o resultado. O certo é buscar o dado ou deixar claro que ele falta.')
    ], { hint: 'Repetido infla os totais; vazio precisa de uma decisão consciente, nunca de um palpite.' }),

  Q('Limpeza: erros e formatos', 'Além de vazios e repetidos, há erros de digitação, textos escritos de jeitos diferentes ("São Paulo", "sao paulo", "S. Paulo"), números guardados como texto e valores impossíveis. Padronizar deixa tudo igual para o computador contar certo.',
    '"São Paulo", "sao paulo" e "S. Paulo" são a mesma cidade\nIdade 250 → provável erro de digitação', 'Encontre inconsistências numa tabela e escolha a correção certa.', [
      num('Quantos jeitos diferentes de escrever a cidade aparecem na tabela?', 4, 'Aparecem "São Paulo", "sao paulo", "S. Paulo" e "São Paulo " (com espaço no fim): **4 jeitos** para uma cidade só.', { table: tab(['Cliente', 'Cidade'], [['Ana', 'São Paulo'], ['Bruno', 'sao paulo'], ['Carla', 'S. Paulo'], ['Diego', 'São Paulo '], ['Elisa', 'São Paulo']], { title: 'Clientes' }), calc: () => new Set(['São Paulo', 'sao paulo', 'S. Paulo', 'São Paulo ']).size }),
      mc('Por que isso atrapalha a análise?', 'O computador conta cada jeito de escrever como se fosse uma cidade diferente', ['Porque o computador não entende nomes de cidade', 'Porque a tabela fica com colunas demais', 'Não atrapalha: o computador junta sozinho'], 'Para o computador, "sao paulo" e "São Paulo" são **textos diferentes**. Ao contar clientes por cidade, eles ficam separados.'),
      mc('Qual é a melhor correção para a coluna Cidade?', 'Padronizar tudo para "São Paulo"', ['Apagar a coluna Cidade', 'Manter os 4 jeitos e contar cada um', 'Deixar só a primeira linha e apagar o resto'], '**Padronizar** é escolher uma forma só e usá-la em todas as linhas.'),
      mc('Uma coluna de Idade tem o valor 250. O mais provável é que:', 'seja um erro de digitação (talvez 25 ou 50) e precise ser conferido', ['seja a idade de uma pessoa muito especial', 'esteja certo, porque dados nunca erram', 'represente 250 meses, sem nenhuma dúvida'], 'Ninguém tem 250 anos. É um **valor impossível**: confira na fonte antes de usar.'),
      multi('Quais destes são problemas de qualidade que a limpeza resolve?', ['Valor guardado como texto ("R$ 120,00")', 'Datas escritas em formatos diferentes', 'Espaços sobrando antes ou depois do texto'], ['O gráfico estar na cor azul', 'O título do relatório estar longo'], 'Texto no lugar de número, **datas em formatos diferentes** e **espaços** sobrando são sujeiras dos dados. Cor e título são questões de apresentação.')
    ], { hint: 'Pergunte: o computador vai achar que estas duas coisas são iguais? Se não, é preciso padronizar.' }),

  Q('Contando e somando', 'Contar mostra quantas vezes algo aparece (frequência). Somar mostra o total de uma quantidade (valor, peças). Uma tabela de frequência lista cada valor e quantas vezes ele aparece, e é o primeiro resumo de qualquer dado.',
    'Pastel  4\nSuco    3\nPizza   2\nPudim   1\nTotal  10', 'Monte uma tabela de frequência a partir de uma lista e calcule porcentagens.', [
      num('Quantas vezes o Pastel aparece na lista de vendas do dia?', 4, 'Contando na lista: Pastel aparece **4 vezes**.', { text: 'Vendas do dia: Pastel, Suco, Pastel, Pizza, Pastel, Suco, Pudim, Pizza, Pastel, Suco', calc: () => ['Pastel', 'Suco', 'Pastel', 'Pizza', 'Pastel', 'Suco', 'Pudim', 'Pizza', 'Pastel', 'Suco'].filter(x => x === 'Pastel').length }),
      num('Quantos produtos DIFERENTES foram vendidos no dia?', 4, 'Os produtos sem repetir são Pastel, Suco, Pizza e Pudim: **4**.', { text: 'Vendas do dia: Pastel, Suco, Pastel, Pizza, Pastel, Suco, Pudim, Pizza, Pastel, Suco', calc: () => new Set(['Pastel', 'Suco', 'Pastel', 'Pizza', 'Pastel', 'Suco', 'Pudim', 'Pizza', 'Pastel', 'Suco']).size }),
      mc('Olhando a tabela de frequência, qual produto foi o mais vendido?', 'Pastel', ['Suco', 'Pizza', 'Pudim'], 'O **Pastel** tem a maior frequência (4 vendas).', { table: tab(['Produto', 'Vendas'], [['Pastel', 4], ['Suco', 3], ['Pizza', 2], ['Pudim', 1]], { title: 'Tabela de frequência' }), calc: () => 'Pastel' }),
      num('Que porcentagem das vendas do dia foi de Pastel (4 de 10)?', 40, '4 ÷ 10 = 0,4, ou **40%**.', { tol: 0.1, unit: '%', calc: () => 4 / 10 * 100 }),
      order('Coloque na ordem os passos para montar uma tabela de frequência:', ['Listar cada valor diferente uma única vez', 'Contar quantas vezes cada valor aparece', 'Conferir se a soma das contagens bate com o total de itens', 'Ordenar do mais frequente para o menos frequente'], 'Listamos os valores, contamos, **conferimos o total** (para não esquecer ninguém) e ordenamos para ver quem lidera.')
    ], { hint: 'Frequência é só "quantas vezes aparece". Confira sempre se a soma das contagens fecha com o total.' }),

  Q('Média, mediana e moda', 'A média é a soma dos valores dividida pela quantidade deles. A mediana é o valor do meio quando os números estão em ordem. A moda é o valor que mais se repete. Cada uma resume os dados de um jeito.',
    'Notas: 4, 8, 6, 5, 3, 8, 9\nMédia  = 43 ÷ 7 ≈ 6,14\nMediana (em ordem: 3 4 5 6 8 8 9) = 6\nModa = 8', 'Calcule média, mediana e moda de uma lista de notas.', [
      num('Qual é a média das notas? (arredonde para 2 casas decimais)', 6.14, 'Soma = 43 e são 7 notas: 43 ÷ 7 = **6,14**.', { tol: 0.01, text: 'Notas da turma: 4, 8, 6, 5, 3, 8, 9', calc: () => r2(avg([4, 8, 6, 5, 3, 8, 9])) }),
      num('Qual é a mediana das notas?', 6, 'Em ordem: 3, 4, 5, **6**, 8, 8, 9. O valor do meio é **6**.', { text: 'Notas da turma: 4, 8, 6, 5, 3, 8, 9', calc: () => med([4, 8, 6, 5, 3, 8, 9]) }),
      num('Qual é a moda das notas?', 8, 'O 8 aparece duas vezes e todos os outros uma só: a moda é **8**.', { text: 'Notas da turma: 4, 8, 6, 5, 3, 8, 9', calc: () => { const f = {}; [4, 8, 6, 5, 3, 8, 9].forEach(x => f[x] = (f[x] || 0) + 1); return +Object.keys(f).sort((a, b) => f[b] - f[a])[0]; } }),
      match('Ligue cada medida a como ela é calculada:', [['Média', 'Soma de todos os valores dividida pela quantidade'], ['Mediana', 'Valor do meio, com os números em ordem'], ['Moda', 'Valor que mais se repete']], '**Média** soma e divide, **mediana** olha o meio e **moda** olha o que mais aparece.'),
      mc('Qual medida usar para descobrir a cor de camiseta mais vendida?', 'Moda: a cor que mais se repete', ['Média: somar as cores e dividir', 'Mediana: a cor do meio da lista', 'Nenhuma: cor não pode ser analisada'], 'Cor é um dado **categórico**: não dá para somar nem ordenar. A moda mostra a que **mais aparece**.')
    ], { hint: 'Para a mediana, primeiro coloque os números em ordem crescente.' }),

  Q('Quando a média engana', 'A média é sensível a valores muito fora do normal (outliers). Um único salário gigante puxa a média para cima e ela deixa de representar o grupo. Nesses casos, a mediana mostra melhor o que é "típico".',
    'Salários: 2000, 2100, 2200, 2300, 2400, 30000\nMédia ≈ 6833  (puxada pelo 30000)\nMediana = 2250', 'Veja como um valor extremo muda a média e quando a mediana é a melhor escolha.', [
      num('Qual é a média dos salários da equipe? (arredonde para o inteiro mais próximo)', 6833, 'Soma = 41 000, dividido por 6 pessoas = 6 833,33. O salário de 30 000 puxou a média para cima.', { tol: 1, unit: 'reais', table: tab(['Pessoa', 'Salário'], [['Ana', 2000], ['Bruno', 2100], ['Carla', 2200], ['Diego', 2300], ['Elisa', 2400], ['Fábio (diretor)', 30000]], { title: 'Salários da equipe', fmt: { 1: 'moeda' } }), calc: () => Math.round(avg([2000, 2100, 2200, 2300, 2400, 30000])) }),
      num('Qual é a mediana dos salários?', 2250, 'Em ordem, os dois do meio são 2 200 e 2 300. A mediana é (2 200 + 2 300) ÷ 2 = **2 250**.', { unit: 'reais', table: tab(['Pessoa', 'Salário'], [['Ana', 2000], ['Bruno', 2100], ['Carla', 2200], ['Diego', 2300], ['Elisa', 2400], ['Fábio (diretor)', 30000]], { title: 'Salários da equipe', fmt: { 1: 'moeda' } }), calc: () => med([2000, 2100, 2200, 2300, 2400, 30000]) }),
      mc('Qual medida descreve melhor o salário "típico" dessa equipe?', 'A mediana, porque não é puxada pelo valor extremo', ['A média, porque ela usa todos os números', 'Nenhuma das duas serve para salários', 'O maior salário, porque é o mais importante'], 'Um valor extremo (**outlier**) estica a média. A mediana ignora o tamanho dos extremos e fica no meio do grupo.'),
      mc('Uma notícia diz: "O salário médio da empresa é R$ 6.833". Por que desconfiar?', 'A média pode estar inflada por poucos salários muito altos', ['Porque todo salário médio é inventado', 'Porque a média nunca pode passar de R$ 3.000', 'Porque notícias não usam números'], 'Com poucos salários enormes, a média sobe e **esconde** que quase todo mundo ganha bem menos.'),
      multi('Em quais situações a mediana costuma ser melhor que a média?', ['Salários, com poucos valores muito altos', 'Preço de casas, com algumas mansões', 'Tempo de espera, com alguns atendimentos muito demorados'], ['Notas de uma prova em que todos tiraram valores parecidos', 'Contagem de pessoas por sala, todas com 30 alunos'], 'Quando há **valores extremos**, a mediana é mais honesta. Se todos os valores são parecidos, média e mediana quase coincidem.')
    ], { hint: 'Pergunte: existe algum número muito diferente dos outros? Se sim, desconfie da média.' }),

  // ------------------------------------------------------------------ bloco 2: resumir e comparar
  Q('Maior, menor e amplitude', 'O mínimo é o menor valor, o máximo é o maior, e a amplitude é a diferença entre os dois (máximo − mínimo). Colocar os valores em ordem (um ranking) mostra rápido quem está no topo e quem está no fim.',
    'Vendas por mês de 2023:\nmáximo = 64 (Mar)\nmínimo = 12 (Fev)\namplitude = 64 − 12 = 52', 'Leia um gráfico mensal, ache o melhor e o pior mês e calcule a amplitude.', [
      mc('Qual mês teve a MAIOR venda em 2023?', 'Mar', ['Jun', 'Jan', 'Nov'], 'A coluna mais alta é a de **março** (R$ 64,00).', { chart: col(MES, V23, { title: 'Vendas por mês, 2023', fmt: 'moeda' }), calc: () => MES[V23.indexOf(Math.max(...V23))] }),
      mc('Qual mês teve a MENOR venda em 2023?', 'Fev', ['Out', 'Set', 'Jul'], 'A coluna mais baixa é a de **fevereiro** (R$ 12,00). Outubro (R$ 13,00) chega perto, mas é um pouco maior.', { chart: col(MES, V23, { title: 'Vendas por mês, 2023', fmt: 'moeda' }), calc: () => MES[V23.indexOf(Math.min(...V23))] }),
      num('Qual é a amplitude das vendas mensais de 2023 (maior menos menor)?', 52, 'Máximo 64 − mínimo 12 = **52**. A amplitude mostra o quanto as vendas variam de um mês para outro.', { chart: col(MES, V23, { title: 'Vendas por mês, 2023', fmt: 'moeda' }), unit: 'reais', calc: () => Math.max(...V23) - Math.min(...V23) }),
      order('Coloque os meses do que mais vendeu para o que menos vendeu:', ['Mar', 'Jun', 'Abr', 'Ago'], 'Pelos valores da tabela: Mar (64), Jun (50), Abr (40) e Ago (38). Ordenar do maior para o menor é montar um **ranking**.', { table: tab(['Mês', 'Vendas'], [['Ago', 38], ['Mar', 64], ['Abr', 40], ['Jun', 50]], { title: 'Vendas de quatro meses', fmt: { 1: 'moeda' } }) }),
      mc('Junho de 2024 teve a maior venda dos 24 meses (R$ 76,00). Antes de comemorar, o que conferir?', 'Se foi um pico real ou algo pontual, como uma promoção ou um erro de registro', ['Nada: o maior valor é sempre o mais confiável', 'Se o gráfico tem a cor certa para destacar o mês', 'Se os outros meses podem ser apagados da tabela'], 'O máximo pode ser um **valor fora do normal**. Vale entender o motivo antes de usá-lo como exemplo do que a loja consegue vender.'),
      multi('Para que servem o máximo e o mínimo?', ['Descobrir o melhor mês de vendas', 'Descobrir o pior mês, para investigar o motivo', 'Medir o tamanho da diferença entre o melhor e o pior'], ['Saber o valor típico de um mês', 'Descobrir por que o cliente comprou'], 'Máximo e mínimo mostram os **extremos** e a distância entre eles. O valor típico vem da média ou da mediana, e o motivo da compra não está na tabela.')
    ], { hint: 'Amplitude = maior − menor. Olhe o topo e a base das colunas.' }),

  Q('Porcentagem e participação', 'A porcentagem é a parte dividida pelo total, vezes 100. A participação mostra quanto cada parte pesa no total, e as participações de todas as partes somam 100%.',
    'Lanches = 340 ÷ 747 × 100 ≈ 45,5%\nBebidas = 215 ÷ 747 × 100 ≈ 28,8%\nDoces   = 192 ÷ 747 × 100 ≈ 25,7%', 'Calcule a participação de cada categoria no total de vendas.', [
      num('Qual é a participação dos Lanches no total de vendas, em %? (uma casa decimal)', 45.5, '340 ÷ 747 = 0,455, ou **45,5%**.', { tol: 0.1, unit: '%', chart: col(CAT, CAT_V, { title: 'Vendas por categoria (total R$ 747,00)', fmt: 'moeda' }), calc: () => r1(340 / 747 * 100) }),
      num('Qual é a participação das Bebidas, em %? (uma casa decimal)', 28.8, '215 ÷ 747 = 0,2878, ou **28,8%**.', { tol: 0.1, unit: '%', chart: col(CAT, CAT_V, { title: 'Vendas por categoria (total R$ 747,00)', fmt: 'moeda' }), calc: () => r1(215 / 747 * 100) }),
      num('Qual é a participação dos Doces, em %? (uma casa decimal)', 25.7, '192 ÷ 747 = 0,257, ou **25,7%**. Conferindo: 45,5 + 28,8 + 25,7 = 100.', { tol: 0.1, unit: '%', chart: col(CAT, CAT_V, { title: 'Vendas por categoria (total R$ 747,00)', fmt: 'moeda' }), calc: () => r1(192 / 747 * 100) }),
      num('Uma loja teve 200 visitantes e 50 compraram. Qual foi a taxa de compra, em %?', 25, '50 ÷ 200 = 0,25, ou **25%**. Uma taxa compara a parte com o todo.', { unit: '%', calc: () => 50 / 200 * 100 }),
      num('Os Lanches são 45,5% das vendas. Se o total do mês fosse R$ 1.000, quantos reais seriam de Lanches?', 455, '45,5% de 1.000 = 0,455 × 1.000 = **R$ 455,00**.', { unit: 'reais', calc: () => 1000 * 0.455 }),
      mc('Uma categoria passou a ter 60% de participação. Isso quer dizer que ela vendeu mais do que antes?', 'Não necessariamente: a participação também sobe se as outras categorias venderem menos', ['Sim, porque 60% é mais da metade do total', 'Sim, participação alta mostra sempre o crescimento', 'Não, participação só vale para números inteiros'], 'Participação é uma **fatia do total**. Ela pode subir porque a categoria cresceu ou porque as outras caíram: olhe também os valores.')
    ], { hint: 'Porcentagem = parte ÷ total × 100. Confira se as partes somam 100%.' }),

  Q('Variação: quanto mudou', 'A variação absoluta é o valor novo menos o antigo. A variação percentual divide essa diferença pelo valor ANTIGO: (novo − antigo) ÷ antigo × 100. A base da conta é sempre o valor de antes.',
    '2023: 396  →  2024: 351\nvariação = 351 − 396 = −45\nvariação % = −45 ÷ 396 × 100 ≈ −11,4%', 'Calcule variações absolutas e percentuais e veja por que a base importa.', [
      num('Quantos reais as vendas CAÍRAM de 2023 para 2024? (digite só o número, sem sinal)', 45, '351 − 396 = **−45**. A variação absoluta é negativa: o sinal de menos mostra que as vendas **caíram** R$ 45,00.', { chart: col(['2023', '2024'], [sum(V23), sum(V24)], { title: 'Total de vendas por ano', fmt: 'moeda' }), unit: 'reais', calc: () => sum(V23) - sum(V24) }),
      mc('A variação das vendas de 396 para 351 foi −45. O que o sinal de menos quer dizer?', 'Que o valor diminuiu', ['Que o valor dobrou', 'Que a conta foi feita errada', 'Que o valor ficou igual'], 'Variação **positiva** é aumento; variação **negativa** é queda; zero é o mesmo valor.'),
      num('De quantos % foi a QUEDA das vendas de 2023 para 2024? (uma casa decimal, sem sinal)', 11.4, '−45 ÷ 396 = −0,1136, ou **−11,4%**: uma queda de 11,4%. A base é o valor antigo (2023).', { tol: 0.1, unit: '%', chart: col(['2023', '2024'], [sum(V23), sum(V24)], { title: 'Total de vendas por ano', fmt: 'moeda' }), calc: () => r1((sum(V23) - sum(V24)) / sum(V23) * 100) }),
      num('Um produto foi de 50 para 100 unidades vendidas. Qual foi o aumento percentual, em %?', 100, '(100 − 50) ÷ 50 = 1, ou **+100%**: as vendas dobraram.', { unit: '%', calc: () => (100 - 50) / 50 * 100 }),
      num('Depois o mesmo produto caiu de 100 para 50 unidades. De quantos % foi a queda? (sem sinal)', 50, '(50 − 100) ÷ 100 = −0,5, ou **−50%**: uma queda de 50%. A base agora é 100, e não 50.', { unit: '%', calc: () => (100 - 50) / 100 * 100 }),
      mc('Por que subir 100% e depois cair 50% leva de volta ao ponto de partida, e não a −100%?', 'Porque cada porcentagem é calculada sobre uma base diferente', ['Porque a segunda conta foi feita com erro', 'Porque porcentagens negativas valem metade', 'Porque o computador arredonda a conta'], 'Cada variação usa **o valor de antes** como base. A base da subida era 50; a da queda era 100.'),
      mc('Qual produto cresceu mais em PORCENTAGEM, de um mês para o outro?', 'Pudim', ['Pastel', 'Pizza', 'Os três cresceram igual'], 'Pastel: +25%. **Pudim: +50%**. Pizza: +6%. Pizza ganhou mais em reais (+30), mas sobre uma base muito maior.', { table: tab(['Produto', 'Mês 1', 'Mês 2'], [['Pastel', 80, 100], ['Pudim', 20, 30], ['Pizza', 500, 530]], { title: 'Vendas por produto', fmt: { 1: 'moeda', 2: 'moeda' } }), calc: () => ['Pastel', 'Pudim', 'Pizza'][[100 / 80, 30 / 20, 530 / 500].indexOf(Math.max(100 / 80, 30 / 20, 530 / 500))] }),
      mc('Na mesma tabela, qual produto cresceu mais em REAIS?', 'Pizza', ['Pastel', 'Pudim', 'Os três cresceram igual'], 'Pizza subiu 530 − 500 = **R$ 30,00**, contra R$ 20,00 do Pastel e R$ 10,00 do Pudim. Porcentagem e valor contam histórias diferentes.', { table: tab(['Produto', 'Mês 1', 'Mês 2'], [['Pastel', 80, 100], ['Pudim', 20, 30], ['Pizza', 500, 530]], { title: 'Vendas por produto', fmt: { 1: 'moeda', 2: 'moeda' } }), calc: () => 'Pizza' })
    ], { hint: 'Variação % = (novo − antigo) ÷ antigo × 100. A base é sempre o valor de antes.' }),

  Q('Comparar com justiça', 'Comparar totais pode enganar quando os grupos têm tamanhos diferentes. Para comparar com justiça, use taxas e médias: vendas por funcionário, casos por mil habitantes, vendas por metro quadrado.',
    'Loja Bairro: 3600 ÷ 4 = 900 por funcionário\nLoja Centro: 5000 ÷ 10 = 500 por funcionário', 'Veja como o total esconde a diferença e calcule valores "por pessoa".', [
      mc('Qual loja vendeu mais em TOTAL?', 'Shopping', ['Centro', 'Bairro', 'As três venderam igual'], 'O maior total é o da loja **Shopping** (R$ 7.200,00). Mas as lojas têm equipes de tamanhos bem diferentes.', { table: tab(['Loja', 'Vendas', 'Funcionários'], [['Centro', 5000, 10], ['Bairro', 3600, 4], ['Shopping', 7200, 12]], { title: 'Lojas', fmt: { 1: 'moeda' } }), calc: () => 'Shopping' }),
      num('Quanto a loja Bairro vendeu POR FUNCIONÁRIO?', 900, '3.600 ÷ 4 = **R$ 900,00** por funcionário.', { unit: 'reais', table: tab(['Loja', 'Vendas', 'Funcionários'], [['Centro', 5000, 10], ['Bairro', 3600, 4], ['Shopping', 7200, 12]], { title: 'Lojas', fmt: { 1: 'moeda' } }), calc: () => 3600 / 4 }),
      mc('Qual loja vende mais POR FUNCIONÁRIO?', 'Bairro', ['Centro', 'Shopping', 'As três vendem igual por funcionário'], 'Por funcionário: Centro 500, **Bairro 900** e Shopping 600. A menor loja é a mais produtiva por pessoa.', { table: tab(['Loja', 'Vendas', 'Funcionários'], [['Centro', 5000, 10], ['Bairro', 3600, 4], ['Shopping', 7200, 12]], { title: 'Lojas', fmt: { 1: 'moeda' } }), calc: () => ['Centro', 'Bairro', 'Shopping'][[5000 / 10, 3600 / 4, 7200 / 12].indexOf(Math.max(5000 / 10, 3600 / 4, 7200 / 12))] }),
      mc('A cidade A teve 300 casos de gripe e a cidade B teve 100. A cidade A está pior?', 'Não dá para saber sem olhar o tamanho da população: compare casos por mil habitantes', ['Sim, porque 300 é maior que 100', 'Não, porque cidades pequenas nunca têm gripe', 'Sim, porque a cidade A vem antes na lista'], 'O número bruto não considera o **tamanho** de cada cidade. A taxa por mil habitantes torna a comparação justa.'),
      num('Quantos casos de gripe por mil habitantes teve a cidade B?', 10, '100 casos ÷ 10 mil habitantes = **10 casos por mil**. Na cidade A foram 300 ÷ 60 = 5 por mil: a B está pior.', { table: tab(['Cidade', 'Casos', 'Habitantes (mil)'], [['A', 300, 60], ['B', 100, 10]], { title: 'Casos de gripe' }), calc: () => 100 / 10 }),
      multi('Quais comparações são justas?', ['Vendas por funcionário em lojas de tamanhos diferentes', 'A porcentagem de clientes que compraram em cada canal', 'Vendas por metro quadrado de duas lojas'], ['O total de vendas de uma loja com 2 funcionários contra outra com 20', 'O número de reclamações de uma empresa enorme contra uma pequena'], 'Taxas e médias colocam os grupos **na mesma escala**. Totais de grupos de tamanhos muito diferentes não são comparáveis.')
    ], { hint: 'Dividir pelo tamanho do grupo (pessoas, metros, habitantes) deixa a comparação justa.' }),

  Q('Agrupar e resumir', 'Agrupar é juntar as linhas por uma característica (canal, produto, mês) e resumir cada grupo com uma soma, uma contagem ou uma média. É o que fazem as tabelas dinâmicas e os gráficos de colunas.',
    'Linhas do canal Loja:   18 + 30 + 6 + 21 = 75\nLinhas do canal Online: 12 + 24 + 40 + 9 = 85', 'Agrupe uma tabela de vendas por canal e por produto.', [
      num('Qual é o total do canal Loja?', 75, '18 + 30 + 6 + 21 = **75**.', { unit: 'reais', table: tab(['Canal', 'Produto', 'Valor'], [['Loja', 'Pastel', 18], ['Online', 'Suco', 12], ['Loja', 'Pizza', 30], ['Online', 'Pastel', 24], ['Loja', 'Suco', 6], ['Online', 'Pizza', 40], ['Loja', 'Pastel', 21], ['Online', 'Suco', 9]], { title: 'Vendas', fmt: { 2: 'moeda' } }), calc: () => 18 + 30 + 6 + 21 }),
      num('Qual é o total do canal Online?', 85, '12 + 24 + 40 + 9 = **85**.', { unit: 'reais', table: tab(['Canal', 'Produto', 'Valor'], [['Loja', 'Pastel', 18], ['Online', 'Suco', 12], ['Loja', 'Pizza', 30], ['Online', 'Pastel', 24], ['Loja', 'Suco', 6], ['Online', 'Pizza', 40], ['Loja', 'Pastel', 21], ['Online', 'Suco', 9]], { title: 'Vendas', fmt: { 2: 'moeda' } }), calc: () => 12 + 24 + 40 + 9 }),
      num('Agora agrupe por PRODUTO: qual é o total do Pastel (nos dois canais)?', 63, '18 + 24 + 21 = **63**. Mesma tabela, outro agrupamento, outra resposta.', { unit: 'reais', table: tab(['Canal', 'Produto', 'Valor'], [['Loja', 'Pastel', 18], ['Online', 'Suco', 12], ['Loja', 'Pizza', 30], ['Online', 'Pastel', 24], ['Loja', 'Suco', 6], ['Online', 'Pizza', 40], ['Loja', 'Pastel', 21], ['Online', 'Suco', 9]], { title: 'Vendas', fmt: { 2: 'moeda' } }), calc: () => 18 + 24 + 21 }),
      mc('Qual produto vendeu mais no total?', 'Pizza', ['Pastel', 'Suco', 'Pastel e Pizza empataram'], 'Pizza: 30 + 40 = **70**. Pastel: 63. Suco: 27.', { table: tab(['Produto', 'Total'], [['Pastel', 63], ['Suco', 27], ['Pizza', 70]], { title: 'Total por produto', fmt: { 1: 'moeda' } }), calc: () => 'Pizza' }),
      num('Qual é o valor MÉDIO por venda no canal Loja? (soma ÷ número de vendas)', 18.75, 'O canal Loja tem 4 vendas somando 75: 75 ÷ 4 = **18,75**.', { tol: 0.01, unit: 'reais', table: tab(['Canal', 'Produto', 'Valor'], [['Loja', 'Pastel', 18], ['Online', 'Suco', 12], ['Loja', 'Pizza', 30], ['Online', 'Pastel', 24], ['Loja', 'Suco', 6], ['Online', 'Pizza', 40], ['Loja', 'Pastel', 21], ['Online', 'Suco', 9]], { title: 'Vendas', fmt: { 2: 'moeda' } }), calc: () => r2(75 / 4) }),
      mc('Para agrupar as vendas por MÊS, o que a tabela precisa ter?', 'Uma coluna com a data (ou o mês) de cada venda', ['Uma coluna com o nome do vendedor', 'Só a coluna de valor', 'Nada: o computador adivinha o mês'], 'Só dá para agrupar por uma característica que **existe na tabela**. Sem a data, não há como saber em que mês cada venda aconteceu.')
    ], { hint: 'Agrupar = separar as linhas em grupos e fazer a mesma conta (soma, média) em cada um.' }),

  Q('Tendência e sazonalidade', 'A tendência é o rumo geral dos dados no tempo: subindo, caindo ou parado. A sazonalidade é um padrão que se repete (sorvete vende mais todo verão). Um pico isolado não é tendência, e a média móvel ajuda a enxergar o rumo sem o "ruído" de cada mês.',
    'Alunos por mês: 20, 24, 29, 33, 38, 41\n→ tendência de alta (+4,2 por mês em média)', 'Descubra a tendência, calcule uma média móvel e separe pico de padrão.', [
      mc('Qual é a tendência do número de alunos?', 'Alta', ['Queda', 'Estável', 'Não existe nenhum padrão'], 'A linha **sobe** mês após mês: de 20 para 41 alunos.', { chart: col(MES.slice(0, 6), [20, 24, 29, 33, 38, 41], { type: 'line', title: 'Alunos matriculados por mês' }), calc: () => 'Alta' }),
      num('Em média, quantos alunos a mais entraram por mês, de janeiro a junho?', 4.2, '(41 − 20) ÷ 5 intervalos entre os 6 meses = **4,2 alunos por mês**.', { tol: 0.01, chart: col(MES.slice(0, 6), [20, 24, 29, 33, 38, 41], { type: 'line', title: 'Alunos matriculados por mês' }), calc: () => (41 - 20) / 5 }),
      num('Qual é a média móvel de 3 meses para março (média de jan, fev e mar)? (duas casas decimais)', 37.67, '(37 + 12 + 64) ÷ 3 = 113 ÷ 3 = **37,67**. A média móvel suaviza os altos e baixos.', { tol: 0.01, unit: 'reais', chart: col(MES, V23, { type: 'line', title: 'Vendas por mês, 2023', fmt: 'moeda' }), calc: () => r2(avg(V23.slice(0, 3))) }),
      mc('Uma sorveteria vende mais todo mês de dezembro, ano após ano. Isso é:', 'Sazonalidade', ['Tendência de queda', 'Um erro nos dados', 'Um valor extremo sem explicação'], 'Um padrão que **se repete** em épocas parecidas é sazonalidade.'),
      mc('Em 2024 as vendas foram R$ 76,00 em junho e R$ 14,00 em julho. Isso prova uma tendência de queda?', 'Não: um pico isolado não é tendência; é preciso olhar vários meses', ['Sim: dois meses seguidos bastam para provar', 'Sim: o último valor é sempre o que manda', 'Não, porque o gráfico de linhas não serve para tendência'], 'Tendência pede **vários períodos**. Junho foi um pico, e a queda de julho pode ser só a volta ao normal.', { chart: col(MES, V24, { type: 'line', title: 'Vendas por mês, 2024', fmt: 'moeda' }) }),
      multi('Quais cuidados ajudam a falar de tendência com segurança?', ['Olhar vários períodos, e não só dois', 'Verificar se existe sazonalidade', 'Comparar meses iguais (dezembro com dezembro)'], ['Usar só o último mês', 'Escolher o período que prova o que eu quero'], 'Mais períodos, atenção à sazonalidade e comparações justas protegem a conclusão. Escolher só o trecho conveniente é **manipular** o resultado.')
    ], { hint: 'Tendência é o rumo de vários períodos. Um único mês fora do normal é pico.' }),

  Q('Relação não é causa', 'Duas coisas podem andar juntas (correlação) sem que uma cause a outra. O gráfico de dispersão mostra isso: pontos subindo são uma relação positiva, pontos descendo são negativa. Muitas vezes existe uma terceira causa escondida.',
    'Calor ↑ → sorvete ↑ (andam juntos)\nSorvete ↑ → afogamento ↑? Não: o calor causa os dois', 'Leia um gráfico de dispersão e separe correlação de causa.', [
      mc('O que o gráfico de dispersão mostra?', 'Com mais calor, as vendas de sorvete também sobem', ['Com mais calor, as vendas de sorvete diminuem bastante', 'Temperatura e vendas de sorvete não têm relação nenhuma', 'As vendas de sorvete é que esquentam o dia'], 'Os pontos **sobem da esquerda para a direita**: é uma relação positiva entre temperatura e vendas.', { chart: { type: 'scatter', title: 'Temperatura e sorvetes vendidos', xlabel: 'Temperatura (°C)', ylabel: 'Sorvetes', series: [{ name: 'Dias', points: [[22, 30], [25, 38], [27, 45], [30, 60], [32, 72], [35, 85]] }] } }),
      num('Quantos sorvetes a MAIS foram vendidos no dia mais quente do que no dia mais frio?', 55, 'Dia mais quente (35 °C): 85 sorvetes. Dia mais frio (22 °C): 30. A diferença é 85 − 30 = **55**.', { table: tab(['Dia', 'Temperatura', 'Sorvetes'], [['Seg', 22, 30], ['Ter', 25, 38], ['Qua', 27, 45], ['Qui', 30, 60], ['Sex', 32, 72], ['Sáb', 35, 85]], { title: 'Dias de calor' }), calc: () => 85 - 30 }),
      mc('Cidades com mais sorveterias têm mais afogamentos. Comer sorvete causa afogamento?', 'Não: o calor causa as duas coisas ao mesmo tempo', ['Sim: quem come sorvete se distrai e acaba se afogando', 'Sim: as duas coisas sobem juntas, então uma causa a outra', 'Não dá para dizer nada sobre calor, sorvete ou praia'], 'Existe uma **terceira causa escondida**, o calor, que aumenta as duas coisas ao mesmo tempo.'),
      match('Ligue cada situação ao tipo de relação:', [['Mais horas de estudo, notas mais altas', 'Relação positiva'], ['Mais atrasos no mês, menos pontos de bônus', 'Relação negativa'], ['Cor do carro e nota numa prova', 'Sem relação aparente']], 'Quando as duas sobem juntas a relação é **positiva**; quando uma sobe e a outra desce é **negativa**; sem padrão, não há relação aparente.'),
      mc('Um relatório diz: "quem usa o aplicativo compra mais". O que perguntar antes de concluir que o aplicativo faz comprar mais?', 'Se não é o contrário: quem compra muito usa mais o aplicativo', ['Se o ícone do aplicativo é bonito e fácil de achar', 'Se o relatório foi escrito com letras bem grandes', 'Nada: toda relação já mostra qual é a causa'], 'A causa pode ser **inversa** (quem compra muito usa mais o aplicativo) ou haver outra causa. Correlação não prova qual vem primeiro.'),
      multi('O que ajuda a mostrar que A realmente causa B?', ['Um teste comparando quem recebeu A e quem não recebeu', 'Descartar uma terceira causa que explique as duas coisas'], ['As duas curvas subirem no mesmo período', 'Ter achado uma correlação muito forte'], 'Para falar em **causa** é preciso um teste justo e descartar outras explicações. Andar junto, mesmo muito forte, só mostra correlação.')
    ], { hint: 'Andar junto não é causar. Pergunte sempre: existe algo escondido que explica as duas?' }),

  Q('Amostra e população', 'A população é todo o grupo que queremos conhecer. A amostra é a parte dele que realmente observamos. Uma boa amostra é sorteada e grande o bastante; uma amostra escolhida de qualquer jeito (enviesada) leva a conclusões erradas.',
    'População: 800 clientes\nAmostra: 40 sorteados\n30 de 40 gostaram → 75% → estimativa para todos: 600', 'Calcule com amostras e reconheça uma amostra enviesada.', [
      num('Uma loja tem 800 clientes e pesquisou 40. Que porcentagem da população foi pesquisada, em %?', 5, '40 ÷ 800 = 0,05, ou **5%**.', { unit: '%', calc: () => 40 / 800 * 100 }),
      num('Dos 40 clientes pesquisados, 30 gostaram do atendimento. Qual a porcentagem de satisfação na amostra, em %?', 75, '30 ÷ 40 = 0,75, ou **75%**.', { unit: '%', calc: () => 30 / 40 * 100 }),
      num('Se a amostra for representativa, quantos dos 800 clientes se espera que gostem do atendimento?', 600, '75% de 800 = 0,75 × 800 = **600 clientes**. É uma **estimativa**, não uma certeza.', { calc: () => 0.75 * 800 }),
      mc('Qual é a melhor forma de escolher a amostra de clientes?', 'Sortear os clientes de uma lista completa', ['Perguntar só aos amigos do dono', 'Pegar só quem estava na loja na hora do almoço de terça', 'Ficar com os 10 primeiros que responderem'], 'Um **sorteio** dá a todos a mesma chance de entrar. Os outros jeitos escolhem um tipo de cliente só.'),
      mc('Quanto maior uma amostra bem sorteada, mais:', 'confiável tende a ser a estimativa', ['colorido fica o gráfico', 'caro o relatório, sem nenhum ganho', 'diferente da população ela fica'], 'Amostras maiores e bem sorteadas **reduzem o erro** da estimativa.'),
      multi('Quais destas pesquisas têm amostra enviesada?', ['Satisfação medida só entre quem reclama no site', 'Enquete política feita só num grupo de mensagens de um partido', 'Qualidade de um lote avaliada só pelas caixas da frente da pilha'], ['Sorteio de 50 clientes entre todos os cadastrados', 'Pesquisa com clientes de todas as lojas escolhidos ao acaso'], 'Quando só um tipo de pessoa ou de item tem chance de entrar, a amostra é **enviesada**. O sorteio entre todos é a forma mais justa.')
    ], { hint: 'Amostra boa = sorteada entre todos e grande o bastante. A conta é sempre parte ÷ total.' }),

  Q('Escolhendo o gráfico', 'Cada pergunta pede um gráfico: comparar categorias (colunas ou barras), mostrar o tempo (linhas), mostrar partes de um todo (pizza, só com poucas fatias), ver a relação entre duas medidas (dispersão) ou mostrar um número só (cartão).',
    'Comparar → colunas · Tempo → linhas · Partes → pizza\nRelação → dispersão · Um valor → cartão', 'Ligue cada pergunta ao gráfico certo e monte dois visuais.', [
      match('Ligue cada pergunta ao gráfico mais indicado:', [['Qual categoria vende mais?', 'Colunas'], ['Como as vendas mudaram mês a mês?', 'Linhas'], ['Quanto cada canal pesa no total?', 'Pizza'], ['Temperatura e sorvete andam juntos?', 'Dispersão'], ['Quanto vendemos hoje?', 'Cartão']], 'Comparar categorias pede **colunas**, o tempo pede **linhas**, partes de um todo pedem **pizza**, relação pede **dispersão** e um número só pede um **cartão**.'),
      mc('Por que evitar uma pizza com 12 fatias?', 'Fica difícil comparar fatias parecidas entre si', ['Porque a pizza só aceita três cores no máximo', 'Porque o computador não consegue desenhar fatias pequenas', 'Porque o gráfico de pizza é proibido em relatórios'], 'O olho compara **comprimentos** (colunas) bem melhor do que **ângulos** de fatias, ainda mais quando são muitas.'),
      build('Monte um gráfico de COLUNAS com o Total de Vendas de cada categoria de produto.', 'loja', ['Produtos[Categoria]', 'Produtos[Produto]', 'Clientes[Cidade]', 'Calendario[Ano]', 'Vendas[Canal]'], { 'Total Vendas': 'SUM(Vendas[Valor])', 'Qtd Vendida': 'SUM(Vendas[Qtd])' }, ['column', 'line', 'pie', 'card'], { v: 'column', axis: 'Produtos[Categoria]', values: 'Total Vendas' }, 'Comparar categorias pede **colunas**: a categoria vai no eixo e a medida nos valores.'),
      build('Monte um gráfico de LINHAS mostrando como o Total de Vendas mudou de um ano para o outro.', 'loja', ['Produtos[Categoria]', 'Produtos[Produto]', 'Clientes[Cidade]', 'Calendario[Ano]', 'Vendas[Canal]'], { 'Total Vendas': 'SUM(Vendas[Valor])', 'Qtd Vendida': 'SUM(Vendas[Qtd])' }, ['column', 'line', 'pie', 'card'], { v: 'line', axis: 'Calendario[Ano]', values: 'Total Vendas' }, 'A evolução no **tempo** pede linhas: o ano vai no eixo e a medida nos valores.'),
      mc('Você precisa comparar 10 produtos com nomes bem longos. Qual gráfico funciona melhor?', 'Barras horizontais, porque os nomes cabem ao lado', ['Pizza com dez fatias coloridas e legenda separada', 'Colunas com os nomes girados na vertical, bem apertados', 'Um cartão para cada produto, todos na mesma tela'], 'Em **barras horizontais** os nomes longos ficam legíveis, e as barras são fáceis de comparar.'),
      mc('Quando uma tabela é melhor do que um gráfico?', 'Quando a pessoa precisa consultar valores exatos', ['Quando queremos mostrar uma tendência no tempo', 'Quando o público não gosta de números', 'Nunca: gráfico é sempre melhor'], 'A **tabela** serve para consulta e valores exatos. O gráfico serve para ver padrões e comparações de relance.')
    ], { hint: 'Antes de escolher o gráfico, escreva a pergunta que ele precisa responder.' }),

  Q('Revisão: resumir e comparar', 'Esta lição reúne o bloco: totais, variação, participação, qual produto caiu e como contar o resultado em uma frase. Use as contas que você aprendeu nas lições 11 a 19.',
    'Total T1 = 400 · Total T2 = 452\nvariação = (452 − 400) ÷ 400 = +13%', 'Resuma uma tabela de vendas por trimestre: totais, variação e participação.', [
      num('Qual foi o total de vendas no 1º trimestre (T1)?', 400, '120 + 80 + 200 = **400**.', { unit: 'reais', table: tab(['Produto', 'T1', 'T2'], [['Pastel', 120, 150], ['Suco', 80, 72], ['Pizza', 200, 230]], { title: 'Vendas por trimestre', fmt: { 1: 'moeda', 2: 'moeda' } }), calc: () => 120 + 80 + 200 }),
      num('Qual foi o total de vendas no 2º trimestre (T2)?', 452, '150 + 72 + 230 = **452**.', { unit: 'reais', table: tab(['Produto', 'T1', 'T2'], [['Pastel', 120, 150], ['Suco', 80, 72], ['Pizza', 200, 230]], { title: 'Vendas por trimestre', fmt: { 1: 'moeda', 2: 'moeda' } }), calc: () => 150 + 72 + 230 }),
      num('Qual foi a variação percentual do total, de T1 para T2, em %?', 13, '(452 − 400) ÷ 400 = 0,13, ou **+13%**.', { unit: '%', calc: () => (452 - 400) / 400 * 100 }),
      mc('Qual produto vendeu MENOS no T2 do que no T1?', 'Suco', ['Pastel', 'Pizza', 'Nenhum: todos cresceram'], 'O Suco foi de 80 para 72: **queda de 8** (−10%). Pastel e Pizza cresceram.', { table: tab(['Produto', 'T1', 'T2'], [['Pastel', 120, 150], ['Suco', 80, 72], ['Pizza', 200, 230]], { title: 'Vendas por trimestre', fmt: { 1: 'moeda', 2: 'moeda' } }), calc: () => 'Suco' }),
      num('Qual foi a participação da Pizza no total do T2, em %? (uma casa decimal)', 50.9, '230 ÷ 452 = 0,5088, ou **50,9%**: mais da metade das vendas.', { tol: 0.1, unit: '%', calc: () => r1(230 / 452 * 100) }),
      mc('Qual frase resume melhor o trimestre para o chefe?', 'As vendas subiram 13%, puxadas por Pastel e Pizza, e só o Suco caiu', ['As vendas mudaram bastante em todos os produtos', 'A Pizza é o produto mais importante da loja inteira', 'Os números estão na tabela, basta o chefe olhar'], 'Uma boa frase dá o **número**, **o que puxou** e **o que merece atenção**, sem exagerar nem deixar o leitor sozinho com a tabela.')
    ], { hint: 'Faça uma conta de cada vez: totais primeiro, depois variação e participação.' }),

  // ------------------------------------------------------------------ bloco 3: visualizar e contar a história
  Q('Gráficos que enganam', 'Um gráfico pode dizer a verdade ou enganar sem ter nenhum número errado. O truque mais comum é cortar o eixo: quando as colunas não começam no zero, uma diferença pequena parece enorme. Outros truques: escalas diferentes lado a lado e mostrar só o período que favorece.',
    'Vendas: 95 → 98 (+3,2%)\nEixo começando em 90: a coluna do segundo mês parece 1,6 vezes maior', 'Veja um gráfico de eixo cortado, calcule o aumento real e aprenda a não ser enganado.', [
      mc('O que o gráfico faz parecer?', 'Que as vendas do mês 2 são bem maiores que as do mês 1', ['Que as vendas ficaram exatamente iguais nos dois meses', 'Que as vendas caíram bastante do mês 1 para o mês 2', 'Que o eixo está correto e o gráfico é totalmente honesto'], 'Como as colunas **começam em 90 e não em zero**, a diferença parece enorme. Na verdade os valores são 95 e 98.', { chart: col(['Mês 1', 'Mês 2'], [95, 98], { min: 90, title: 'Vendas (R$)', fmt: 'moeda' }) }),
      num('Qual foi o aumento REAL das vendas, em %? (uma casa decimal)', 3.2, '(98 − 95) ÷ 95 = 0,0316, ou **+3,2%**: um aumento pequeno.', { tol: 0.1, unit: '%', calc: () => r1((98 - 95) / 95 * 100) }),
      num('Com o eixo começando em 90, a altura da coluna é "valor − 90". Quantas vezes a coluna do mês 2 parece maior que a do mês 1?', 1.6, 'Alturas desenhadas: 98 − 90 = 8 e 95 − 90 = 5. Então 8 ÷ 5 = **1,6 vez**, quando o aumento real é de só 1,03 vez.', { tol: 0.01, calc: () => (98 - 90) / (95 - 90) }),
      mc('Qual é a regra para o eixo de um gráfico de COLUNAS?', 'Começar no zero, para a altura ser proporcional', ['Ele pode começar em qualquer número, sem avisar ninguém', 'Ele deve começar sempre no menor valor da tabela', 'Ele nunca precisa de números escritos nas marcas'], 'A coluna comunica o valor pelo **tamanho**. Se o eixo não começa no zero, o tamanho deixa de ser proporcional.'),
      multi('Quais destes truques fazem um gráfico enganar?', ['Eixo de colunas que não começa no zero', 'Dois gráficos lado a lado com escalas diferentes', 'Mostrar só o período que favorece a conclusão'], ['Eixo de colunas começando no zero', 'Escala igual nos gráficos que serão comparados'], 'Eixo cortado, escalas diferentes e período escolhido a dedo **distorcem a leitura**. Zero no eixo e mesma escala são práticas honestas.'),
      mc('Em um gráfico de LINHAS, o eixo pode não começar no zero?', 'Pode, se estiver claro e sem exagerar a variação', ['Nunca: todo eixo precisa começar no zero, sem exceção', 'Sempre: pode começar onde quiser, sem avisar', 'Só em gráficos de pizza e nos de rosca'], 'Nas **linhas** o que importa é a forma da variação, então um eixo cortado pode ser aceito, mas precisa ser visível e honesto.')
    ], { hint: 'Pergunte: se eu tirasse os números do gráfico, a impressão continuaria honesta?' }),

  Q('Gráfico limpo e claro', 'Um gráfico claro tem só o que ajuda a entender. Retire o que distrai (3D, sombras, grades pesadas, cores demais), escolha o tipo certo, destaque o ponto principal com uma cor e escreva um título que diga a conclusão.',
    'Cinza para o resto, uma cor forte para o destaque.\nPoucos elementos, tudo com função.', 'Aprenda a limpar um gráfico e a destacar o que importa.', [
      mc('Por que evitar gráficos em 3D?', 'A profundidade distorce o tamanho das colunas', ['O 3D deixa o gráfico mais barato para imprimir em papel', 'O 3D só funciona em gráficos de linhas', 'O 3D é proibido por lei nos relatórios'], 'No 3D, partes da frente parecem **maiores** que as de trás, e fica difícil comparar valores com precisão.'),
      multi('O que costuma deixar um gráfico poluído?', ['Linhas de grade fortes demais', 'Dez cores sem nenhum significado', 'Efeitos 3D e sombras'], ['Um título que diz a conclusão', 'Rótulos nos valores mais importantes'], 'Grades pesadas, cores sem sentido e efeitos **distraem**. Título claro e rótulos úteis ajudam.'),
      mc('Qual é a melhor forma de destacar que os Lanches lideram as vendas?', 'Pintar os Lanches de cor forte e o resto de cinza', ['Pintar cada categoria de uma cor diferente e vibrante', 'Aumentar igualmente todas as letras do gráfico', 'Colocar uma imagem chamativa no fundo'], 'Uma **cor de destaque** leva o olho direto ao ponto principal. Muitas cores competem entre si.'),
      order('Coloque na ordem os passos para melhorar um gráfico:', ['Decidir a mensagem principal', 'Escolher o tipo de gráfico certo', 'Remover o que não ajuda (3D, grades, cores demais)', 'Destacar o ponto principal com uma cor', 'Escrever um título claro'], 'Primeiro a **mensagem**, depois o tipo certo, depois a limpeza, o destaque e, por fim, o título que fecha a ideia.'),
      match('Ligue cada elemento do gráfico ao seu papel:', [['Título', 'Diz a conclusão em uma frase'], ['Eixos e unidades', 'Mostram o que está sendo medido'], ['Cor de destaque', 'Leva o olho ao ponto principal'], ['Fonte dos dados', 'Mostra de onde vieram os números']], 'Cada elemento tem **uma função**. Se ele não ajuda a entender, pode sair.'),
      mc('O que ajuda na leitura deste gráfico?', 'As barras estão ordenadas, do maior para o menor valor', ['Ele usa três dimensões só para parecer mais moderno e vistoso', 'Ele tem dezenas de cores sem nenhum significado', 'Ele esconde os valores para o leitor adivinhar'], '**Ordenar** as barras mostra o ranking sem esforço. Os valores escritos dispensam o leitor de adivinhar.', { chart: { type: 'bar', title: 'Vendas por categoria', cats: ['Lanches', 'Bebidas', 'Doces'], series: [{ name: '', values: [340, 215, 192] }], fmt: 'moeda' } })
    ], { hint: 'Tudo no gráfico deve ter uma função. O que não ajuda, atrapalha.' }),

  Q('Títulos que contam algo', 'O leitor olha o título primeiro. Um título descritivo só diz o assunto ("Vendas por categoria"). Um título de conclusão diz o que o gráfico mostra ("Lanches responde por quase metade das vendas") e poupa o trabalho de interpretar.',
    'Descritivo:  "Vendas por categoria"\nConclusão:   "Lanches responde por quase metade das vendas"', 'Troque títulos descritivos por títulos de conclusão e escreva o seu.', [
      match('Ligue cada título descritivo ao título de conclusão correspondente:', [['Vendas por categoria', 'Lanches responde por quase metade das vendas'], ['Vendas por mês', 'Março vendeu mais de cinco vezes o valor de fevereiro'], ['Vendas por ano', 'As vendas caíram 11% de 2023 para 2024']], 'O título de conclusão traz o **achado principal**, com número ou comparação.'),
      mc('Qual é o melhor título para o gráfico de colunas das categorias (Lanches 340, Bebidas 215, Doces 192)?', 'Lanches lidera: quase metade das vendas da loja', ['Gráfico de vendas', 'Categorias e valores em reais', 'Vendas (R$) por categoria de produto'], 'Só o primeiro **conta o que o gráfico mostra**. Os outros dizem apenas o assunto.', { chart: col(CAT, CAT_V, { fmt: 'moeda' }) }),
      mc('Qual destes títulos é só descritivo, sem contar uma conclusão?', 'Vendas por categoria', ['Lanches vende 77% a mais que Doces', 'As vendas caíram 11% em 2024', 'O Online já é 45% das vendas de março'], 'Os outros três trazem um **resultado** (um número e uma comparação). "Vendas por categoria" diz só o assunto.'),
      multi('Um bom título de conclusão:', ['Diz o que o leitor deve perceber', 'Cabe em uma frase curta', 'Traz um número ou uma comparação'], ['Tem o nome do arquivo e a data de hoje', 'É escrito em letras gigantes para chamar atenção'], 'Título bom é **curto, claro e traz o achado**. Nome de arquivo e letras enormes não ajudam a entender.'),
      write('Escreva, com as suas palavras, um título que conte a conclusão do gráfico (Lanches 340, Bebidas 215, Doces 192).', ['!qual categoria é o destaque :: lanche', '!o que ela tem de especial :: lider|mais|maior|maioria|metade|45|topo|primeir|domin|destaq'], 'Lanches é a categoria que mais vende, com quase metade do total', 'Um bom título cita **quem** se destaca (Lanches) e **o quê** (lidera, vende mais, quase metade).', { chart: col(CAT, CAT_V, { title: 'Vendas por categoria', fmt: 'moeda' }) }),
      mc('Onde o leitor costuma olhar primeiro num gráfico?', 'No título: por isso ele deve entregar a mensagem', ['Na legenda, em letras pequenas', 'No canto da fonte dos dados', 'No último número da tabela'], 'O **título** é a porta de entrada. Se ele já diz a conclusão, o gráfico serve de prova.')
    ], { hint: 'Um bom título responde: "o que esse gráfico quer me dizer?"' }),

  Q('Conhecer o público', 'A mesma análise precisa ser contada de jeitos diferentes. A diretoria quer poucas conclusões e a decisão; o time técnico quer método e detalhes; o cliente quer uma linguagem simples. Antes de montar, pergunte quem vai ouvir e o que essa pessoa precisa decidir.',
    'Diretoria (5 min): 1 ou 2 conclusões + decisão\nTime técnico: método e tabelas\nCliente leigo: linguagem simples', 'Adapte a apresentação ao público certo.', [
      match('Ligue cada público ao que ele mais precisa:', [['Diretoria, com 5 minutos', 'Poucas conclusões e a decisão necessária'], ['Time que usa a análise no dia a dia', 'Detalhes, método e tabelas completas'], ['Cliente que não conhece o assunto', 'Linguagem simples, sem termos técnicos']], 'Quem tem **pouco tempo** quer o essencial; quem **usa** a análise quer o detalhe; quem **não conhece** quer clareza.'),
      mc('Você vai apresentar à diretoria em 5 minutos. O que levar?', 'Uma ou duas conclusões claras e a decisão que elas pedem', ['As 40 tabelas completas que você montou na análise', 'O passo a passo de cada correção feita na limpeza dos dados', 'Um gráfico novo para cada linha da base de dados'], 'Em pouco tempo, vale o **essencial**. O detalhe fica à mão, num anexo, para quem perguntar.'),
      multi('Antes de montar a apresentação, o que perguntar sobre o público?', ['Que decisão essa pessoa precisa tomar?', 'Quanto tempo ela tem?', 'Que termos ela já conhece?'], ['Qual é a cor favorita dela?', 'Quantos gráficos cabem em cada slide?'], 'Decisão, **tempo** e **vocabulário** guiam o que mostrar. A cor favorita e o tamanho do slide não mudam a mensagem.'),
      mc('Um cliente leigo não conhece a palavra "mediana". O que fazer?', 'Explicar com palavras simples, como "o valor do meio"', ['Usar a palavra sem explicar', 'Trocar por um gráfico em 3D', 'Não mostrar esse número'], 'Linguagem simples não é "falar mais baixo": é **traduzir** o termo para o que o público já entende.'),
      num('A diretoria reservou 20 minutos e você quer deixar 25% do tempo para perguntas. Quantos minutos sobram para apresentar?', 15, '25% de 20 = 5 minutos de perguntas. Sobram 20 − 5 = **15 minutos**.', { unit: 'minutos', calc: () => 20 - 20 * 0.25 }),
      order('Coloque na ordem o preparo de uma apresentação:', ['Saber quem vai ouvir e que decisão precisa tomar', 'Escolher a mensagem principal', 'Escolher os gráficos que provam a mensagem', 'Ensaiar dentro do tempo disponível'], 'O **público** vem primeiro, porque ele decide a mensagem, os gráficos e o tempo.')
    ], { hint: 'Quem vai ouvir? Quanto tempo tem? O que precisa decidir?' }),

  Q('Do dado ao insight', 'Um dado é um número solto. Uma comparação dá sentido ao número. Um insight explica o que a comparação significa e por que importa para quem decide.',
    'Dado:       Lanches vendeu R$ 340,00\nComparação: 77% a mais que Doces\nInsight:    Lanches é o motor da loja: se faltar, a venda cai muito', 'Suba os degraus: dado, comparação e insight.', [
      match('Ligue cada frase ao seu nível:', [['Dado puro', 'Lanches vendeu R$ 340,00'], ['Comparação', 'Lanches vendeu 77% a mais que os Doces'], ['Insight', 'Lanches responde por quase metade da receita: se faltar estoque, a loja perde muito']], 'O dado é o número, a comparação o **coloca ao lado de outro**, e o insight diz **o que isso significa**.'),
      num('Quantos % a mais vendeu a categoria Lanches (340) do que Doces (192)? (uma casa decimal)', 77.1, '(340 − 192) ÷ 192 = 0,771, ou **77,1% a mais**. A base é Doces, a categoria com a qual comparamos.', { tol: 0.1, unit: '%', calc: () => r1((340 - 192) / 192 * 100) }),
      mc('Qual frase é um insight, e não só um dado?', 'Lanches vende mais que as outras duas categorias, então o estoque dele não pode faltar', ['Lanches vendeu R$ 340,00', 'A tabela tem três categorias', 'O gráfico é de colunas'], 'Só a primeira frase faz uma **comparação** e diz **o que fazer com ela**.'),
      multi('Um bom insight costuma ter:', ['Um número ou comparação que o sustente', 'Uma explicação do que isso significa', 'Uma razão pela qual importa para quem decide'], ['Muitos termos técnicos para parecer sério', 'Uma opinião sem nenhum dado por trás'], '**Evidência, significado e importância** formam um insight. Termos difíceis e opinião sem dados não.'),
      write('Escreva um insight sobre o gráfico: não repita só o número, diga o que ele significa.', ['!qual categoria :: lanche', '!compara com as outras :: mais|maior|lider|metade|45|77|acima|superior|domin', '!o que significa ou por que importa :: import|depend|risco|perd|foco|priorid|estoque|cuidar|principal|motor|forte|essencial|signific|quer dizer'], 'Lanches vende mais que as outras duas categorias, então é o principal motor da loja e o estoque dele não pode faltar', 'Um insight cita **quem** (Lanches), **compara** (vende mais) e diz **por que importa** (motor da loja, estoque).', { chart: col(CAT, CAT_V, { title: 'Vendas por categoria', fmt: 'moeda' }) }),
      mc('Por que "Vendemos R$ 747,00" ainda não é um insight?', 'Porque é só um número: falta comparar e explicar o que significa', ['Porque o valor está errado', 'Porque insights não podem ter números', 'Porque só a diretoria pode ter insights'], 'Sem **comparação** (com o mês passado, com a meta) o número fica solto e não leva a nenhuma decisão.')
    ], { hint: 'Insight = dado + comparação + significado.' }),

  Q('A estrutura da história', 'Uma boa apresentação conta uma história com começo, meio e fim. O começo traz o contexto e a pergunta, o meio traz as descobertas com seus gráficos, e o fim traz a conclusão e o que fazer. A conclusão principal pode aparecer logo no começo, para quem tem pouco tempo.',
    'Começo: contexto e pergunta\nMeio: descobertas com gráficos\nFim: conclusão e ação', 'Monte a estrutura de uma apresentação e resuma uma história em uma frase.', [
      order('Coloque as partes da apresentação na ordem:', ['Contexto e pergunta', 'Principais descobertas, uma por gráfico', 'Conclusão', 'Recomendação e próximos passos'], 'Primeiro situamos o público, depois mostramos as **provas**, depois concluímos e dizemos **o que fazer**.'),
      match('Ligue cada parte à sua função:', [['Começo', 'Dizer o contexto e a pergunta que será respondida'], ['Meio', 'Mostrar as descobertas com gráficos que provam'], ['Fim', 'Concluir e dizer o que fazer']], 'Cada parte tem **um trabalho**: situar, provar e fechar com uma ação.'),
      mc('Onde colocar a conclusão principal para um chefe sem tempo?', 'Logo no começo, resumida, e repetida no fim junto com a ação', ['Só no último slide, como uma surpresa', 'Escondida no meio, entre os detalhes', 'Em lugar nenhum: o gráfico fala sozinho'], 'Quem tem pouco tempo precisa da **resposta primeiro**. Os detalhes ficam para quem quiser conferir.'),
      multi('Cada gráfico de uma apresentação deve:', ['Responder a uma pergunta ou provar uma ideia', 'Ter um título que diz a conclusão', 'Ter só o que ajuda a entender'], ['Aparecer só porque ficou bonito', 'Repetir o mesmo número de outro gráfico sem ligação'], 'Todo gráfico precisa de **um motivo**. Se ele só enfeita ou repete, sai.'),
      write('Resuma em uma frase a história dos trimestres (T1 = 400, T2 = 452; Pastel e Pizza cresceram e o Suco caiu).', ['!o que aconteceu com o total :: subiu|subiram|cresc|aument|alta|13', '!o que puxou o resultado :: pastel|pizza', '!o que merece atenção :: suco|caiu|queda|cair|diminu'], 'As vendas subiram 13% no trimestre, puxadas por Pastel e Pizza, mas o Suco caiu', 'A frase da história traz **o resultado**, **o que o puxou** e **o ponto de atenção**.', { table: tab(['Produto', 'T1', 'T2'], [['Pastel', 120, 150], ['Suco', 80, 72], ['Pizza', 200, 230]], { title: 'Vendas por trimestre', fmt: { 1: 'moeda', 2: 'moeda' } }) }),
      mc('Quantas ideias centrais uma apresentação curta deve ter?', 'Uma ideia central, apoiada por poucas descobertas', ['Dez ideias de importância igual', 'Uma ideia nova a cada gráfico, sem ligação', 'Nenhuma: basta mostrar os dados'], 'Uma **mensagem central** é lembrada. Muitas ideias soltas se perdem.')
    ], { hint: 'Contexto → provas → conclusão → ação.' }),

  Q('Da conclusão à recomendação', 'Depois do insight vem a pergunta "e daí?". A recomendação diz o que fazer, quem faz, quando e qual resultado se espera, sempre apoiada pelos dados. Se os dados não bastam, diga o que falta e proponha um teste pequeno.',
    'Dado: venda média Online R$ 21,25 · Loja R$ 18,75\nRecomendação: incentivar o canal Online', 'Transforme um insight em uma recomendação com impacto estimado.', [
      mc('Qual é uma boa recomendação?', 'Incentivar o canal Online, porque cada venda lá vale R$ 21,25, contra R$ 18,75 na loja', ['O canal Online tem vendas todos os meses', 'Os dados são interessantes e merecem muita atenção', 'É preciso fazer alguma coisa a respeito das vendas'], 'Uma boa recomendação diz **o que fazer** e traz o **dado que a sustenta**.'),
      num('Cada venda Online vale R$ 21,25 e cada venda da loja R$ 18,75. Se 100 vendas passarem da loja para o Online, quantos reais a receita aumenta?', 250, 'A diferença por venda é 21,25 − 18,75 = 2,50. Para 100 vendas: 2,50 × 100 = **R$ 250,00**.', { unit: 'reais', calc: () => (21.25 - 18.75) * 100 }),
      multi('Uma boa recomendação inclui:', ['O que fazer', 'Quem faz e até quando', 'O resultado esperado, com o dado que a sustenta'], ['Uma lista de todos os dados que você olhou', 'Um pedido de desculpas por ter analisado'], 'Ação, **responsável e prazo**, e resultado esperado tornam a recomendação possível de cumprir.'),
      order('Coloque na ordem o caminho do dado à ação:', ['Dado: a venda média Online é maior que a da loja', 'Insight: cada venda Online vale mais', 'Recomendação: incentivar o canal Online', 'Ação: lançar uma promoção de frete grátis no Online'], 'Do **dado** ao **insight**, do insight à **recomendação**, e dela à **ação** concreta.'),
      write('Escreva uma recomendação para a loja com base nesses números (venda média Online R$ 21,25 contra R$ 18,75 da loja).', ['!o que fazer :: invest|ampli|aument|incentiv|promov|priori|foc|expand|divulg|cresc', '!em qual canal :: online', '!por que, com o dado :: ticket|valor medio|venda media|vale mais|21|18|maior|mais|receita'], 'Incentivar o canal Online, porque cada venda lá vale mais, R$ 21,25, do que na loja', 'A recomendação diz **o que fazer** (incentivar), **onde** (Online) e **por quê** (venda mais valiosa).'),
      mc('Se os dados não bastam para uma recomendação firme, o que fazer?', 'Dizer o que se sabe, o que falta e propor um teste pequeno', ['Inventar números para ter certeza', 'Recomendar mesmo assim, com total convicção', 'Esconder a dúvida para não parecer inseguro'], 'Honestidade sobre a **incerteza** gera confiança, e um teste pequeno traz os dados que faltam.')
    ], { hint: 'Depois do insight, pergunte: e daí? O que fazer, quem, quando?' }),

  Q('Montando um painel', 'Um painel (dashboard) junta poucos visuais para responder a pergunta do público de uma vez. Os números mais importantes ficam no alto e à esquerda, o estilo é o mesmo em tudo, e cada visual tem um título claro.',
    'Alto: cartões com os números-chave\nMeio: evolução no tempo e ranking\nLado: segmentação para filtrar', 'Entenda o papel de cada visual e monte três deles.', [
      match('Ligue cada visual ao seu papel no painel:', [['Cartão', 'Mostra o número-chave, como o total de vendas'], ['Gráfico de linhas', 'Mostra a evolução no tempo'], ['Barras ordenadas', 'Mostram o ranking entre categorias'], ['Segmentação', 'Deixa o leitor filtrar o painel']], 'Cada visual responde **um tipo de pergunta**: quanto, como mudou, quem lidera e como filtrar.'),
      mc('Onde ficam os números mais importantes numa página?', 'No alto e à esquerda, onde o olho começa a ler', ['No canto de baixo, em letra pequena', 'Escondidos em uma segunda página', 'Misturados entre os gráficos, sem destaque'], 'Lemos de cima para baixo e da esquerda para a direita. O **mais importante** deve estar onde o olho chega primeiro.'),
      build('Monte um CARTÃO com o Total de Vendas.', 'loja', ['Produtos[Categoria]', 'Produtos[Produto]', 'Clientes[Cidade]', 'Calendario[Ano]', 'Vendas[Canal]'], { 'Total Vendas': 'SUM(Vendas[Valor])', 'Qtd Vendida': 'SUM(Vendas[Qtd])' }, ['column', 'card', 'table', 'slicer'], { v: 'card', values: 'Total Vendas' }, 'O **cartão** mostra um número só: basta a medida.'),
      build('Monte uma TABELA com o nome do produto e o Total de Vendas dele.', 'loja', ['Produtos[Categoria]', 'Produtos[Produto]', 'Clientes[Cidade]', 'Calendario[Ano]', 'Vendas[Canal]'], { 'Total Vendas': 'SUM(Vendas[Valor])', 'Qtd Vendida': 'SUM(Vendas[Qtd])' }, ['column', 'card', 'table', 'slicer'], { v: 'table', fields: ['Produtos[Produto]', 'Total Vendas'] }, 'Na **tabela** você marca as colunas desejadas: o produto e a medida.'),
      build('Monte uma SEGMENTAÇÃO para o leitor filtrar o painel por canal.', 'loja', ['Produtos[Categoria]', 'Produtos[Produto]', 'Clientes[Cidade]', 'Calendario[Ano]', 'Vendas[Canal]'], { 'Total Vendas': 'SUM(Vendas[Valor])', 'Qtd Vendida': 'SUM(Vendas[Qtd])' }, ['column', 'card', 'table', 'slicer'], { v: 'slicer', axis: 'Vendas[Canal]' }, 'A **segmentação** recebe só o campo que filtra: o canal de venda.'),
      mc('Quantos visuais cabem bem num painel?', 'Poucos, uns 4 a 6, que respondem à pergunta do público', ['O máximo possível, para mostrar tudo', 'Um para cada coluna da tabela de dados', 'Sempre exatamente vinte'], 'Painel cheio demais **cansa e esconde** a mensagem. Poucos visuais bem escolhidos funcionam melhor.'),
      multi('O que deixa um painel mais fácil de ler?', ['Alinhar os visuais e manter o mesmo estilo', 'Usar poucas cores, com uma para destaque', 'Dar a cada visual um título claro'], ['Colocar o maior número possível de gráficos', 'Usar uma cor diferente em cada coluna, sem motivo'], '**Alinhamento, poucas cores e títulos claros** organizam o olhar. Excesso de gráficos e de cores confunde.')
    ], { hint: 'Pense na pergunta do público e escolha só os visuais que a respondem.' }),

  Q('Ética e honestidade', 'Quem conta uma história com dados tem uma responsabilidade: mostrar o que os números dizem, inclusive o que contraria a sua ideia. Ser honesto é citar a fonte, avisar quando faltam dados, não escolher só o que convém e proteger os dados pessoais das pessoas.',
    'Mostrar o resultado real, mesmo o ruim\nCitar fonte e data\nOcultar nomes e documentos quando não são necessários', 'Decida o que é certo em situações do dia a dia de quem analisa dados.', [
      mc('Os dados mostram que a promoção não aumentou as vendas (−2%). O chefe pede para mostrar só o mês bom. O que fazer?', 'Mostrar o resultado real e propor o próximo teste', ['Apagar o resultado ruim e mostrar só os bons números', 'Trocar o −2% por um +2% para agradar o chefe', 'Mostrar só o mês bom, sem avisar ninguém'], 'Esconder ou trocar números é **enganar**. O resultado ruim também ensina o que ajustar.'),
      multi('Quais destas são boas práticas de quem apresenta dados?', ['Citar a fonte e a data dos dados', 'Mostrar também os resultados que contrariam a sua ideia', 'Avisar quando há dados faltando ou incertos'], ['Escolher só o período que favorece a conclusão', 'Arredondar os números até o resultado parecer melhor'], 'Fonte, **transparência** e avisos de incerteza dão credibilidade. Escolher a dedo e maquiar números, não.'),
      mc('Seu relatório tem nome, CPF e telefone dos clientes, mas a análise só precisa dos totais por cidade. O que fazer?', 'Ocultar os dados pessoais e deixar só o necessário', ['Manter tudo, porque mais dado é sempre melhor', 'Enviar a planilha completa por mensagem para facilitar', 'Trocar o CPF pelo número de telefone'], 'Dados pessoais só devem aparecer **quando necessários**. Para totais por cidade, eles ficam de fora.'),
      match('Ligue cada prática ao nome do problema:', [['Escolher só o período que favorece a conclusão', 'Seleção enviesada de dados'], ['Cortar o eixo para exagerar uma diferença', 'Gráfico enganoso'], ['Divulgar nomes e CPFs sem necessidade', 'Quebra de privacidade']], 'Conhecer o **nome do problema** ajuda a reconhecê-lo (e a evitá-lo) no trabalho.'),
      write('Explique, com as suas palavras, por que vale mostrar também os dados que contrariam a sua ideia.', ['!o que acontece com quem decide :: engan|errad|erro|decid|decis|escolh', '!o efeito na confiança :: confian|credib|reputa|honest|verdad'], 'Porque esconder o que contraria a ideia engana quem decide e faz perder a confiança; mostrando tudo a decisão fica melhor', 'Esconder dados **engana quem decide** e **destrói a confiança** em você e nas próximas análises.'),
      mc('Por que citar a fonte e a data dos dados?', 'Para o leitor conferir e saber se os números valem', ['Para o relatório ficar mais comprido e parecer mais sério', 'Para ninguém conseguir refazer a análise', 'Porque o gráfico não funciona sem isso'], 'A **fonte** permite conferir, e a **data** mostra se a informação está atual.')
    ], { hint: 'Pergunte: se o leitor visse todos os dados, ele concordaria com a minha conclusão?' }),

  Q('Revisão final: contando a história', 'Para fechar o curso, vamos juntar tudo num caso: ler uma tabela, calcular, escolher o gráfico, escrever um título e uma recomendação, e conferir a honestidade da história.',
    'Online: 20 → 45 (+125%)\nParticipação em março: 45 ÷ 100 = 45%', 'Conte a história de uma loja que vende na loja física e no Online.', [
      num('Qual foi o total vendido pelo Online no trimestre (jan + fev + mar)?', 95, '20 + 30 + 45 = **95**.', { unit: 'reais', table: tab(['Mês', 'Loja', 'Online'], [['Jan', 60, 20], ['Fev', 58, 30], ['Mar', 55, 45]], { title: 'Vendas por canal', fmt: { 1: 'moeda', 2: 'moeda' } }), calc: () => 20 + 30 + 45 }),
      num('Qual foi a participação do Online nas vendas de março, em %?', 45, 'Março: 55 + 45 = 100 de total. 45 ÷ 100 = **45%**.', { unit: '%', table: tab(['Mês', 'Loja', 'Online'], [['Jan', 60, 20], ['Fev', 58, 30], ['Mar', 55, 45]], { title: 'Vendas por canal', fmt: { 1: 'moeda', 2: 'moeda' } }), calc: () => 45 / (55 + 45) * 100 }),
      num('Qual foi a variação percentual das vendas Online de janeiro para março, em %?', 125, '(45 − 20) ÷ 20 = 1,25, ou **+125%**.', { unit: '%', table: tab(['Mês', 'Loja', 'Online'], [['Jan', 60, 20], ['Fev', 58, 30], ['Mar', 55, 45]], { title: 'Vendas por canal', fmt: { 1: 'moeda', 2: 'moeda' } }), calc: () => (45 - 20) / 20 * 100 }),
      mc('Qual gráfico mostra melhor a evolução dos dois canais nos três meses?', 'Linhas, com uma linha para a Loja e outra para o Online', ['Pizza com seis fatias (mês e canal)', 'Um cartão com o total do trimestre', 'Dispersão da Loja contra o Online'], 'Evolução no tempo pede **linhas**, e duas séries mostram a Loja caindo enquanto o Online sobe.'),
      mc('Qual é o melhor título para esse gráfico?', 'O Online cresceu 125% em três meses e já é 45% das vendas de março', ['Vendas por canal e por mês', 'Loja e Online: janeiro, fevereiro e março', 'Os canais de venda estão mudando muito'], 'O título de **conclusão** traz o número e a comparação. Os outros só descrevem o assunto ou são vagos.'),
      write('Escreva uma frase de recomendação para a diretoria, apoiada nos números.', ['!o que fazer :: invest|ampli|reforc|priori|foc|aument|expand|incentiv', '!em qual canal :: online', '!com base em qual dado :: cresc|125|45|subiu|alta|expans'], 'Reforçar os investimentos no Online, que cresceu 125% em três meses e já responde por 45% das vendas', 'A recomendação diz **o que fazer**, **onde** e **com base em qual dado**.', { table: tab(['Mês', 'Loja', 'Online'], [['Jan', 60, 20], ['Fev', 58, 30], ['Mar', 55, 45]], { title: 'Vendas por canal', fmt: { 1: 'moeda', 2: 'moeda' } }) }),
      multi('Antes de apresentar, o que conferir?', ['Se os números fecham com a tabela', 'Se o gráfico tem eixo honesto e título claro', 'Se a recomendação nasce dos dados'], ['Se o fundo do slide combina com a cor do sapato', 'Se alguma conclusão ruim pode ser apagada'], 'Conferir **números, gráfico honesto e recomendação ligada aos dados** protege a sua credibilidade.')
    ], { hint: 'Vá devagar: primeiro as contas, depois a escolha do gráfico, depois o texto.' })
];
